INSERT INTO `programs` (`id`, `region`, `city`, `university`, `school`, `program`, `category`, `direction`, `background`, `cycle`, `intake`, `duration`, `updated`, `academic`, `language`, `tests`, `prerequisites`, `deadline`, `deadline_note`, `tuition`, `application_requirements`, `interview`, `rent_budget`, `positioning`, `source`, `source_label`, `requirements_json`, `documents_json`, `notes_json`, `sources_json`, `source_payload_json`) VALUES ('ntu-mfe', '新加坡', 'Singapore', 'Nanyang Technological University', 'Nanyang Business School', 'MSc Financial Engineering', '金融与量化', '金融工程', '量化背景', '最近可用', '下一入学周期', '约1年全日制', '2026-06-05', '在线申请、成绩单、简历、推荐/推荐人信息、文书；数理/金融/编程背景；部分申请者面试', 'TOEFL/IELTS按NTU要求；GRE/GMAT如官网建议/要求', 'TOEFL/IELTS按NTU要求；GRE/GMAT如官网建议/要求', 'NTU MFE历史悠久，适合亚洲金融工程、risk、quant路径', '通常每年秋季入学，申请窗口约前一年下半年至次年初；以NTU NBS官网为准', '来自 2026-06-05 项目详表；如当年页面尚未发布，使用最近可用官方信息。', 'NTU项目学费以NBS MSc Financial Engineering最新fee为准；通常SGD数万级别', '在线申请、成绩单、简历、推荐/推荐人信息、文书；数理/金融/编程背景；部分申请者面试', '可能面试', 'Singapore西部/Jurong/Pioneer：studio/1BR约SGD 2,500-4,000/月；合租单间约SGD 900-1,600/月', '高匹配', 'https://www.ntu.edu.sg/business/admissions/graduate-studies/msc-financial-engineering', '用户项目详表', '[{"label":"学术背景","value":"量化基础","level":86},{"label":"英语要求","value":"按项目要求","level":68},{"label":"标化考试","value":"按当年政策","level":42}]', '["在线申请、成绩单、简历、推荐/推荐人信息、文书","数理/金融/编程背景","部分申请者面试"]', '["与NUS MFE可双申","新加坡租房需尽早预算"]', '[{"label":"项目官网 / 最近可用招生页","url":"https://www.ntu.edu.sg/business/admissions/graduate-studies/msc-financial-engineering","kind":"项目官网","year":"最近可用"}]', '{"02_项目详细库":{"国家/地区":"新加坡","学校":"Nanyang Technological University","位置":"Singapore","学院":"Nanyang Business School","项目":"MSc Financial Engineering","方向":"金融工程","学制":"约1年全日制","学费/费用":"NTU项目学费以NBS MSc Financial Engineering最新fee为准；通常SGD数万级别","申请时间":"通常每年秋季入学，申请窗口约前一年下半年至次年初；以NTU NBS官网为准","申请要求/材料":"在线申请、成绩单、简历、推荐/推荐人信息、文书；数理/金融/编程背景；部分申请者面试","考试要求":"TOEFL/IELTS按NTU要求；GRE/GMAT如官网建议/要求","面试":"可能面试","建议先修/能力":"NTU MFE历史悠久，适合亚洲金融工程、risk、quant路径","周边租房预算":"Singapore西部/Jurong/Pioneer：studio/1BR约SGD 2,500-4,000/月；合租单间约SGD 900-1,600/月","申请定位":"高匹配","备注":"与NUS MFE可双申；新加坡租房需尽早预算","官网来源":"https://www.ntu.edu.sg/business/admissions/graduate-studies/msc-financial-engineering"}}');
