INSERT INTO `guides` (`id`, `section`, `payload_json`, `sort_order`, `updated`) VALUES ('overview', 'overview', '[{"项目":"范围","结论":"美国20个重点项目 + 新加坡NUS/NTU 3个项目；结合原Excel主表与Web查询汇总"},{"项目":"最强冲刺","结论":"Princeton MFin, MIT MFin, Baruch MFE, CMU MSCF, Stanford/Harvard统计"},{"项目":"量化金融核心","结论":"Cornell ORIE FE, Columbia MAFN/MSFE, UChicago FinMath, NYU Courant/Tandon, UCLA MFE"},{"项目":"性价比/匹配","结论":"Georgia Tech QCF, UIUC MSFE, Rutgers MQF, Duke Stats, NUS/NTU MFE"},{"项目":"租房高风险城市","结论":"New York, Boston/Cambridge, Bay Area, Los Angeles, Singapore"},{"项目":"申请策略","结论":"冲刺8-10所、匹配8-10所、保底3-5所；金融工程与统计项目文书主线需分开"},{"项目":"数据说明","结论":"官网信息按2026-06-05可查页面整理；未在官网同页明确列出的学费/DDL以“需核验/估算”标记"}]', 0, '2026-06-05');
