INSERT INTO `guides` (`id`, `section`, `payload_json`, `sort_order`, `updated`) VALUES ('materials', 'materials', '[{"材料类别":"成绩单/学历","具体内容":"中英文成绩单、在读证明/毕业证学位证、GPA说明、排名证明（如有）","适用项目":"所有项目","备注":"需尽早确认是否要求官方寄送或WES/第三方认证"},{"材料类别":"简历","具体内容":"1页英文CV/Resume，突出数学、编程、金融、科研、实习、竞赛","适用项目":"所有项目","备注":"MIT等明确偏好1页；量化项目避免泛泛金融履历"},{"材料类别":"SOP/PS","具体内容":"项目动机、量化能力证据、职业目标、为何该项目","适用项目":"所有项目","备注":"Columbia/Princeton等可能同时要求Academic Statement和Personal Statement"},{"材料类别":"推荐信","具体内容":"通常2-3封，优先数学/统计/CS/金融工程课程老师或量化实习主管","适用项目":"所有项目","备注":"Cornell 2封必需/3封更佳；Princeton/MIT/CMU通常3封"},{"材料类别":"考试","具体内容":"GRE/GMAT、TOEFL/IELTS/DET按项目政策","适用项目":"按项目","备注":"GRE可选不等于没用；顶级quant项目强分数仍有信号价值"},{"材料类别":"视频/面试","具体内容":"视频essay、异步video interview、invite interview、数学/量化assessment","适用项目":"MIT、Cornell、CMU、Baruch、部分NYU/UCLA/NUS/NTU","备注":"提前准备概率、线代、简历项目、金融市场基础和behavioral"},{"材料类别":"作品/补充材料","具体内容":"GitHub、研究论文、量化策略项目、课程项目、Kaggle/竞赛","适用项目":"非强制但推荐","备注":"不要堆材料，选能证明能力的2-3项"},{"材料类别":"资金/签证","具体内容":"存款证明、I-20/DS-2019资料、护照、租房预算","适用项目":"录取后","备注":"美国城市租金差异巨大，NYC/Bay Area/Boston需更高预算"}]', 1, '2026-06-05');
