INSERT INTO `guides` (`id`, `section`, `payload_json`, `sort_order`, `updated`) VALUES ('timeline', 'timeline', '[{"月份":"6-7月","动作":"确定项目池；补齐数学/统计/编程先修；整理英文简历；开成绩单与排名证明","重点项目":"所有项目"},{"月份":"8月","动作":"定稿PS/SOP主线；推荐人沟通；准备GRE/GMAT/TOEFL/IELTS如需","重点项目":"Princeton/CMU/Cornell/MIT/Baruch优先"},{"月份":"9-10月","动作":"完成第一批网申账号、文书初稿、推荐信系统；准备视频题/面试题库","重点项目":"MIT、Baruch、CMU、Cornell、UChicago、NYU"},{"月份":"11-12月","动作":"提交早轮/第一轮；重点检查成绩单、推荐信、考试送分、资金证明","重点项目":"Princeton、Baruch、CMU R1、Cornell、Stanford/Harvard等统计项目"},{"月份":"1月","动作":"提交MIT/Columbia/UCB/UCLA/统计项目；跟进面试与补材料","重点项目":"MIT、Columbia、Berkeley、UCLA、Duke/Yale"},{"月份":"2-3月","动作":"提交第二轮/补申；新加坡NUS/NTU常见窗口跟进","重点项目":"CMU R2、UChicago、NUS、NTU"},{"月份":"4-5月","动作":"Columbia MAFN final及rolling项目收尾；比较offer、押金、签证/住宿","重点项目":"Columbia、NYU、Rutgers、USC、UIUC"}]', 2, '2026-06-05');
