INSERT INTO `guides` (`id`, `section`, `payload_json`, `sort_order`, `updated`) VALUES ('sources', 'sources', '[{"来源":"Princeton MFin apply","URL":"https://bcf.princeton.edu/academic-programs/master-in-finance/apply-for-the-master-in-finance-program/"},{"来源":"Princeton graduate tuition","URL":"https://gradschool.princeton.edu/financial-support/financial-support-model/funding-calendar-university-rates-costs"},{"来源":"Baruch MFE application","URL":"https://mfe.baruch.cuny.edu/application-process/"},{"来源":"MIT MFin admissions","URL":"https://mitsloan.mit.edu/mfin/admissions/how-to-apply"},{"来源":"MIT MFin tuition","URL":"https://mitsloan.mit.edu/mfin/admissions/tuition-and-financial-aid"},{"来源":"Cornell ORIE MEng admissions","URL":"https://www.duffield.cornell.edu/orie/meng/meng-admissions-requirements-ithaca/"},{"来源":"Columbia MAFN admissions","URL":"https://www.math.columbia.edu/mafn/admissions-2/"},{"来源":"Berkeley IEOR MEng apply","URL":"https://ieor.berkeley.edu/academics/master-of-engineering/how-to-apply/"},{"来源":"CMU MSCF apply","URL":"https://www.cmu.edu/mscf/admissions/apply.html"},{"来源":"UChicago FinMath apply","URL":"https://finmath.uchicago.edu/admissions/apply/"},{"来源":"NYU Tandon MSFE","URL":"https://engineering.nyu.edu/academics/programs/financial-engineering-ms"},{"来源":"NYU Courant Math Finance","URL":"https://math.nyu.edu/financial_mathematics/"},{"来源":"UCLA MFE","URL":"https://www.anderson.ucla.edu/degrees/master-of-financial-engineering"},{"来源":"Georgia Tech QCF","URL":"https://qcf.gatech.edu/"},{"来源":"Rutgers MQF","URL":"https://www.business.rutgers.edu/masters-quantitative-finance"},{"来源":"USC MSFE","URL":"https://viterbigradadmission.usc.edu/programs/masters/msprograms/industrial-systems-engineering/ms-financial-engineering/"},{"来源":"UIUC MSFE","URL":"https://msfe.illinois.edu/"},{"来源":"Stanford MS Statistics","URL":"https://statistics.stanford.edu/academics/ms-statistics"},{"来源":"Harvard Statistics","URL":"https://statistics.fas.harvard.edu/"},{"来源":"Yale Statistics and Data Science","URL":"https://statistics.yale.edu/"},{"来源":"Duke Statistical Science","URL":"https://stat.duke.edu/"},{"来源":"NUS MSc Financial Engineering","URL":"https://rmi.nus.edu.sg/mfe/"},{"来源":"NUS MSc Statistics","URL":"https://www.stat.nus.edu.sg/prospective-students/graduate-programme/msc-in-statistics/"},{"来源":"NTU MSc Financial Engineering","URL":"https://www.ntu.edu.sg/business/admissions/graduate-studies/msc-financial-engineering"}]', 3, '2026-06-05');
