INSERT INTO `guides` (`id`, `section`, `payload_json`, `sort_order`, `updated`) VALUES ('originalIndex', 'originalIndex', '[{"学校名称":"Princeton University\n普林斯顿大学","学院名称":"Bendheim Center for Finance\n本德海姆金融中心","项目名称":"Master of Finance (M.Fin.)\n金融硕士(M.Fin.)","项目时长":"2年","先修课程":"At a minimum, we expect applicants to be familiar in mathematics with linear algebra, multivariable calculus, differential equations, and probability and statistics at the level of an intermediate undergraduate course.","是否面试":"是","项目链接":"https://bcf.princeton.edu/master-in-finance/","申请要求":"https://bcf.princeton.edu/academic-programs/master-in-finance/apply-for-the-master-in-finance-program/","录取数据网址":"https://bcf.princeton.edu/academic-programs/master-in-finance/common-questions/","备注":"\n\n1.项目每年招 30-35人左右，25fall入学33学生，中国人占尽60%，这两年录取中国人比例逐步上升。中国学生 陆本偏好清北（尤其偏好北大光华（去年录取四五个），其次是清华，上交），海本偏向Qstop50英美顶尖院校；\n\n2.该项目专注量化领域，聚焦算法交易，量化资产管理，衍生品定价，因此看重申请者高阶量化课程，录取者背景多来自于数理基础强大申请者；偏好数学、工程、量化经济学背景；\n\n3.多数申请者有2-3段头部机构量化实习，垂直领域量化金融实习建议至少6个月以上，40%录取者有全职工作经验；案例：本科康奈尔大学经济计算机双学位，GPA3.85,2，两段校内计算机专业，4段量化实习累积尽10个月； "},{"学校名称":"Baruch College","学院名称":"Weissman School of Arts & Sciences","项目名称":"MS in Financial Engineering ","项目时长":"3学期","先修课程":"Calculus (two semesters)\nProbability (one semester)\nLinear Algebra (one semester)\nC++ (one semester or certificate)\nFinance (one semester, or relevant work experience)","是否面试":"是","项目链接":"https://mfe.baruch.cuny.edu/","申请要求":"https://mfe.baruch.cuny.edu/application-process/","录取数据网址":"https://mfe.baruch.cuny.edu/student-profiles-fall-2024/","备注":"1.项目每年招25-30人左右，25fall526名申请者，录取26名学生，小班教学；\n2.录取BG偏好理工背景，数学和工程背景占比50%，其余录取的学生来自物理、统计等，侧重技能Python，C++为主；\n3.学校不强制有全职工程经验，但录取学生平均累积10-12个月左右实习或工作经验。学校在审核过程中是少有的技术面，主要考察计算机/数学能力技术能力（类似于求职技术面），有全职工作经验在面试环节能呈现技术层面竞争力；\n案例：北大材料科学与工程，绩点3.8+，GRE325+，本科期间修北大数学前置课程和美国院校线上前置课程，毕业后GAP一年基金公司做量化研究员‌交易员岗位；"},{"学校名称":"Massachusetts Institute of Technology\n麻省理工学院","学院名称":"SLOAN SCHOOL OF MANAGEMENT\n斯隆管理学院","项目名称":"Master of Finance\n金融硕士","项目时长":"12- and 18-Month Options","先修课程":"Algebra\nMultivariable Calculus\nProbability Statistics","是否面试":"是","项目链接":"http://mitsloan.mit.edu/mfin/ ","申请要求":"https://mitsloan.mit.edu/mfin#apply","录取数据网址":"https://mitsloan.mit.edu/mfin/apply/class-profile","备注":"1.项目size相对比较大，25届127名申请者入学。对国际学生门槛要求越来越高，陆本优先C9院，平均GPA3.9，偏好海本学生；\n2.录取学生平均工作经验13个月，偏好全职工程经验，本科应届生录取者至少大半年量化实习经验；\n3.录取学生本科背景科学/数学31%，计算机19%、经济商业30%，近两年录取STEM背景占比80%+\n录取：LSE数学经济学，GPA3.8 ，两段强量化，kaggle竞赛银牌，实习强推荐；北大光华金融专业，GPA3.7，近一年实习经验；"},{"学校名称":"Cornell University\n康奈尔大学 ","学院名称":"College of Engineering\n工学院","项目名称":"Cornell Financial Engineering Manhattan(M.Eng Degree)\n康奈尔金融工程","项目时长":"2 semester +1 semester Manhattan Campus","先修课程":"Two semesters of calculus-based probability, statistics, and/or stochastic processes, similar in content and rigor to Cornell courses ENGRD 2700, ORIE 3500 and/or ORIE 3510. Courses in which probability and statistical methods are used, but where theory is not the primary focus are not acceptable substitutes, nor are professional exam credentials (e.g., CFA, FRM).\nAn introductory finance course. Courses in economics and accounting are not acceptable substitutes.\nStrongly recommended: A course in differential equations, similar in content and rigor to Cornell course MATH 2930.\nStrongly recommended: Proficiency with R and/or Python.","是否面试":"Video ","项目链接":"https://www.orie.cornell.edu/orie/programs","申请要求":"https://www.orie.cornell.edu/orie/cfem","录取数据网址":"https://www.orie.cornell.edu/orie/programs/meng-degree-ithaca/admissions","备注":""},{"学校名称":"Columbia University\n哥伦比亚大学","学院名称":"Graduate School of Arts and Sciences\n艺术与科学研究生院","项目名称":"MA in Mathematical Finance\n数学金融学硕士","项目时长":" two or three semesters,","先修课程":"calculus, linear algebra, elementary differential equations, probability, and statistics, and a programming language.","是否面试":"否","项目链接":"http://www.math.columbia.edu/mafn/","申请要求":"http://www.math.columbia.edu/mafn/admissions/application-procedures/","录取数据网址":"https://www.math.columbia.edu/mafn/admissions/admissions-statistics/","备注":""},{"学校名称":"University of California,Berkeley \n加州大学伯克利分校","学院名称":"College of Engineering\n工程学院","项目名称":"Master of Engineering program in Industrial Engineering & Operations Research\nConcentrations： Management Science & Engineering/Fin Tech/Interllectual Property and Entrepreneurship Strategy\n工业工程与运筹学硕士学位\n专业方向:管理科学与工程/金融科技/知识产权与创业战略","项目时长":"one year","先修课程":"To be successful in this program, entering students are expected to have a basic understanding of probability, statistics and optimization, as well as fluency in a programming language.\n\nSpecifically, the FinTech concentration requires college level programming proficiency in Python, C, C++, and/or Java. Students will find knowledge and proficiency in S and R also beneficial.\n","是否面试":"case by case","项目链接":"https://ieor.berkeley.edu/academics/master-of-engineering/","申请要求":"https://ieor.berkeley.edu/academics/master-of-engineering/how-to-apply/","录取数据网址":"NA","备注":"1.UCB的MFE class size每年80人总有，25025年入学84名学生，在TOP量化金融里面属于属于中位数；\n2.偏向录取海本学而思，陆本基本上只会录取清北以及港前三，整体录取难度偏大；\n3.该项目只开设春季项目，录取者工作经验平均2.5年左右，平均年龄25岁，高质量量化经验有优势，非常看重全职工作经验；案例：北大经院 GPA3.8，本科毕业工作一年，大学期间数学竞赛获奖丰富，量化实习经验多段；"},{"学校名称":"Carnegie Mellon University","学院名称":"Tepper School of Business","项目名称":"Master of Science in Computational Finance","项目时长":"3学期","先修课程":"Admissions prerequisites\nCalculus I and II\nLinear algebra\nCalculus-based probability\nA minimum of one semester of an object-oriented programming language course (C++, Java, Python, C#). More than one semester is preferred.","是否面试":"是","项目链接":"https://www.cmu.edu/mscf/news/evaluating-masters-in-financial-engineering-programs.html","申请要求":"https://www.cmu.edu/mscf/admissions/index.html","录取数据网址":"https://www.cmu.edu/mscf/admissions/class-profile.html","备注":"1.项目class size为108人，录取size相对较大，对国际学生友好，国际学生占比78%；项目分为匹茨堡校区和纽约校区，纽约占52，匹茨堡占56人；\n2. 该项目工作经验虽然非必需，但具有相关工作经验会被强烈建议并优先考虑，建议有一年工作经验申请更有竞争力；\n3.学术背景方面强烈偏好数学、统计学、计算机科学、工程或金融等相关领域的本科学位占比最高；华大数学专业，GPA3.86,，3段量化实习，其中一段三中一华，两个量化竞赛金牌，银牌奖项；"},{"学校名称":"University of Chicago","学院名称":"Division of the Physical Sciences","项目名称":"MS in Financial Mathematics","项目时长":"15个月","先修课程":"Mathematics\nAll candidates should have a solid background in mathematics. The minimal math prerequisites are the successful completion of at least multivariable calculus, linear algebra, and probability.\nComputer Programming\nIn addition to academic mathematical training and work experience, candidates must have some level of computer programming skills, ideally in either C++, or Python, or other object-oriented languages. ","是否面试":"是","项目链接":"https://finmath.uchicago.edu/","申请要求":"https://finmath.uchicago.edu/admissions/","录取数据网址":"https://finmath.uchicago.edu/admissions/class-profile/","备注":"1.项目class size为108人，录取size相对较大 2.建议申请者有深厚的数学基础，量化以及编程经验；3，不强制强制工作经验但有丰富实习经验更有优势"}]', 4, '2026-06-05');
