INSERT INTO `guides` (`id`, `section`, `payload_json`, `sort_order`, `updated`) VALUES ('webSummary', 'webSummary', '[{"学校":"Princeton University","项目":"Master in Finance (M.Fin.)","最新公布学费（USD）":"2025-26 regular tuition $65,210 + SHP $3,800 = $69,010/年","学制":"2年（少量学生可压缩为1年）","申请时间/DDL（按官网最新可查）":"Fall 2026 DDL: 2025-12-15 23:59 EST","核心申请要求（精简）":"成绩单（含数学课）、Personal Statement、Academic Statement of Purpose、3封推荐信；所有申请者需参加数学测试；建议数理背景强","英语/GRE/GMAT":"GRE/GMAT可选；英语不达豁免者需TOEFL/IELTS/DET","面试":"官网未写常规面试；有数学assessment","官方来源1":"https://bcf.princeton.edu/academic-programs/master-in-finance/apply-for-the-master-in-finance-program/","官方来源2":"https://gradschool.princeton.edu/financial-support/financial-support-model/funding-calendar-university-rates-costs","备注":"学费按研究生院2025-26标准；2026-27暂未公布"},{"学校":"Baruch College","项目":"MS in Financial Engineering","最新公布学费（USD）":"全项目学费：NY居民$27,675；州外/国际生$42,000","学制":"3学期","申请时间/DDL（按官网最新可查）":"Fall 2026: Round 1 2025-11-01；Round 2 2025-12-01","核心申请要求（精简）":"3封推荐信；先修含2学期Calculus、1学期Probability、1学期Linear Algebra、1学期C++、1学期Finance/相关工作经验","英语/GRE/GMAT":"GRE/GMAT不再要求，改为Quant Background Assessment (QBA)","面试":"是","官方来源1":"https://mfe.baruch.cuny.edu/","官方来源2":"https://mfe.baruch.cuny.edu/about/","备注":"官网FAQ仍写旧学费版本；about页显示较新的全项目学费"},{"学校":"MIT","项目":"Master of Finance","最新公布学费（USD）":"2025-26: 12个月$93,834；18个月$128,820","学制":"12个月或18个月","申请时间/DDL（按官网最新可查）":"2026 entry官网显示已截止；OGE页面列出的DDL为2026-01-05","核心申请要求（精简）":"成绩单、3封推荐信、1页Resume、3个short answers、2个video questions；建议具备线代/多元微积分/概率/统计与Python","英语/GRE/GMAT":"GRE/GMAT可选但强烈建议提交；TOEFL/IELTS不要求申请时提交","面试":"面试为invite-only，且为必经环节","官方来源1":"https://mitsloan.mit.edu/mfin/admissions/how-to-apply","官方来源2":"https://mitsloan.mit.edu/mfin/admissions/tuition-and-financial-aid","备注":"MIT页面对英语要求与其他项目不同，MFin申请阶段不要求TOEFL/IELTS"},{"学校":"Cornell University","项目":"M.Eng. in ORIE – Financial Engineering Concentration","最新公布学费（USD）":"2025-26 M.Eng. tuition $71,266/年；Graduate Student Activity Fee $110/年","学制":"3学期（Fall-Spring-Fall，第三学期在Manhattan）","申请时间/DDL（按官网最新可查）":"Fall admittance: 2025-12-01","核心申请要求（精简）":"简历、SOP、Personal Statement、2封必需/3封更佳推荐；异步视频面试；FE方向额外要求两学期概率统计/随机过程、intro finance，强烈建议微分方程与Python","英语/GRE/GMAT":"GRE/GMAT二选一，GRE preferred；英语按Cornell研究生院要求","面试":"异步video interview","官方来源1":"https://www.duffield.cornell.edu/orie/meng/meng-admissions-requirements-ithaca/","官方来源2":"https://bursar.cornell.edu/students-parents/tuition-rates-and-fees","备注":"此项目不是Cornell Tech，是ORIE M.Eng.下的Financial Engineering concentration"},{"学校":"Columbia University","项目":"MA in Mathematical Finance (MAFN)","最新公布学费（USD）":"2025-26: $47,194/学期（Residence Unit，≤20 points）","学制":"2或3学期","申请时间/DDL（按官网最新可查）":"Fall 2026: early decision 2026-01-15；final deadline 2026-05-01","核心申请要求（精简）":"成绩单、Academic Statement of Purpose、Personal Statement、3封学术推荐信；需具备calculus/linear algebra/ODE/probability/statistics/programming","英语/GRE/GMAT":"GRE/GMAT强烈建议但非必需；国际生英语最低要求见GSAS（TOEFL iBT 100[旧标尺]/IELTS 7.5）","面试":"否","官方来源1":"https://www.math.columbia.edu/mafn/admissions-2/","官方来源2":"https://www.gsas.columbia.edu/content/cost-attendance","备注":"GSAS学费按学期计；总费用取决于修读学期和points"},{"学校":"UC Berkeley","项目":"M.Eng. in IEOR (可选FinTech concentration)","最新公布学费（USD）":"2025-26估算：居民学费与费用$50,446.50；非居民$63,305.50；含SHIP后总学费+费约$58,576.50/$71,435.50","学制":"1年","申请时间/DDL（按官网最新可查）":"Fall 2026 DDL: 2026-01-07（Graduate Division项目页）","核心申请要求（精简）":"在线申请、文书、推荐信、成绩单；IEOR/MEng要求概率统计/优化/编程基础，FinTech方向要求Python/C/C++/Java等编程能力","英语/GRE/GMAT":"GRE要求Yes（IEOR MEng项目页/申请页）；国际生需满足英语要求","面试":"原表写case by case，官网未突出统一面试要求","官方来源1":"https://ieor.berkeley.edu/academics/master-of-engineering/how-to-apply/","官方来源2":"https://funginstitute.berkeley.edu/newadmit/resources/","备注":"你表里这项更接近IEOR MEng/FinTech方向，不是Berkeley Haas/UCB MFE"},{"学校":"Carnegie Mellon University","项目":"MS in Computational Finance (MSCF)","最新公布学费（USD）":"2025-26 tuition $69,000；fees $1,006","学制":"3学期","申请时间/DDL（按官网最新可查）":"Round 1: 2025-12-01；Round 2: 2026-03-01","核心申请要求（精简）":"在线申请、1-2页Resume、正式成绩单/学位证明、2篇short essays+90秒video essay、3封推荐信","英语/GRE/GMAT":"GRE/GMAT二选一必需；国际生通常需Duolingo/TOEFL/IELTS（满足豁免条件可免）","面试":"是，invite-only","官方来源1":"https://www.cmu.edu/mscf/admissions/apply.html","官方来源2":"https://www.cmu.edu/sfs/tuition/graduate/index.html","备注":"官网明确会核验申请材料真实性"},{"学校":"University of Chicago","项目":"MS in Financial Mathematics","最新公布学费（USD）":"2025-26按课程计费：每门100-unit课程$7,862；另有Student Services Fee $503/季度，USHIP 2025为$1,715/季度","学制":"15个月","申请时间/DDL（按官网最新可查）":"Round 1: 2026-01-08；Round 2: 2026-03-26","核心申请要求（精简）":"Resume/CV、所有成绩单、3个candidate statements、2个video statements、3封推荐信（至少1封professional）","英语/GRE/GMAT":"需较强数学与编程基础；英语要求按大学规定，常见最低TOEFL 90 / IELTS 7.0；官网不强调GRE必需","面试":"原表写是，但当前requirements页更强调video statements与材料，不突出常规面试","官方来源1":"https://finmath.uchicago.edu/admissions/application-requirements/","官方来源2":"https://finmath.uchicago.edu/admissions/tuition/","备注":"总学费需按实际修课门数计算，官网以每100-unit课程计价"}]', 5, '2026-06-05');
